import { NextResponse } from "next/server";
import { getAnthropicClient } from "@/lib/anthropic/client";
import Anthropic from "@anthropic-ai/sdk";
import { createClient } from "@/lib/supabase/server";
import { getSupabaseAdminClient } from "@/lib/supabase/admin";
import { z } from "zod";

const SYSTEM_PROMPT = `You are a horticulture expert. Given a plant species, produce a concise, practical care profile.

RETURN ONLY A JSON OBJECT — NO MARKDOWN, NO CODE FENCES, NO PREAMBLE OR EXPLANATION — MATCHING EXACTLY THIS SHAPE:
{
  "watering": { "interval_days_summer": int, "interval_days_winter": int, "method": string, "signs_thirsty": string, "signs_overwatered": string },
  "fertilizing": { "interval_days_growing_season": int, "interval_days_dormant": int or null, "type": string },
  "mist": { "interval_days": int or null, "method": string or null, "notes": string },
  "light": { "level": "bright indirect" | "low" | "direct", "notes": string },
  "humidity": { "level": "low" | "medium" | "high", "notes": string },
  "temperature_range_c": [int, int],
  "toxicity": { "pets": boolean, "notes": string },
  "common_problems": [ { "symptom": string, "cause": string, "fix": string } ],
  "rotation_days": int
}

Rules:
- All intervals are whole numbers of days. "interval_days_dormant" may be null if the plant should not be fertilized while dormant.
- mist is optional; if the plant doesn't benefit from misting, set "interval_days" to null.
- "temperature_range_c" is [min, max] in Celsius.
- "rotation_days" is how often to rotate the pot for even growth (use 0 if unimportant).
- "toxicity.pets" is true if the plant is toxic to pets or domestic animals.
- Provide 2 to 4 entries in "common_problems".
- Output valid JSON and nothing else.`;

export async function POST(request) {
  const supabase = await createClient();
  const admin = await getSupabaseAdminClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

  const body = await request.json();

  if (!body.plantName) return NextResponse.json({ error: "Missing plant name." }, { status: 400 });

  const { plantName, species } = body;

  // Check if we already have a care profile for this species in the database before calling the API
  const { data: existing, error: existingError } = await admin
    .from("care_profiles")
    .select("species_scientific, species_common, profile_json")
    .ilike("species_scientific", species)
    .maybeSingle();

  if (existing?.profile_json) return NextResponse.json(existing.profile_json);

  const mainSchema = z.object({
    watering: z.object({
      interval_days_summer: z.number().int(),
      interval_days_winter: z.number().int().nullable(),
      method: z.string(),
      signs_thirsty: z.string(),
      signs_overwatered: z.string(),
    }),
    fertilizing: z.object({
      interval_days_growing_season: z.number().int(),
      interval_days_dormant: z.number().int().nullable(),
      type: z.string(),
    }),
    mist: z.object({
      interval_days: z.number().int().nullable(),
      method: z.string().nullable(),
      notes: z.string(),
    }),
    light: z.object({
      level: z.string(),
      notes: z.string(),
    }),
    humidity: z.object({
      level: z.string(),
      notes: z.string(),
    }),
    temperature_range_c: z.tuple([z.number().int(), z.number().int()]),
    toxicity: z.object({
      pets: z.boolean(),
      notes: z.string(),
    }),
    common_problems: z.array(z.object({
      symptom: z.string(),
      cause: z.string(),
      fix: z.string(),
    })),
    rotation_days: z.number().int(),
  });

  try {
    const anthropic = getAnthropicClient();

    const response = await anthropic.messages.create({
      model: process.env.ANTHROPIC_AI_MODEL,
      max_tokens: 2048,
      system: [
        {
          type: "text",
          text: SYSTEM_PROMPT,
          cache_control: { type: "ephemeral" },
        }
      ],
      messages: [
        {
          role: "user",
          content: [
            {
              type: "text",
              text: `Plant name: ${plantName}\nSpecies: ${species} \n\nProvide a care profile for this plant in the specified JSON format.`,
            }
          ]
        }
      ]
    })

    const raw = response.content.find((part) => part.type === "text")?.text;

    const result = mainSchema.safeParse(JSON.parse(raw));

    if (!result.success) return NextResponse.json({ error: "Model returned invalid response.", details: result.error.errors }, { status: 502 });

    // Save the generated care profile to the database for future use
    const { data: careData, error: careError } = await admin
      .from("care_profiles")
      .upsert({
        species_scientific: species,
        species_common: plantName || null,
        profile_json: result.data,
        source: "ai",
      })

    return NextResponse.json(result.data);
  } catch (error) {
    if (error instanceof Anthropic.APIError) return NextResponse.json({ error: `Anthropic API error: ${error.message}` }, { status: 502 });
    if (error instanceof Anthropic.RateLimitError) return NextResponse.json({ error: "Anthropic API rate limit exceeded." }, { status: 503 });
    if (error instanceof Anthropic.BadRequestError) return NextResponse.json({ error: `Anthropic API bad request: ${error.message}` }, { status: 400 });
    if (error instanceof Anthropic.InternalServerError) return NextResponse.json({ error: "Anthropic API internal server error." }, { status: 502 });

    return NextResponse.json({ error: "Failed to create care routine for plant." }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getSupabaseAdminClient } from "@/lib/supabase/admin";
import { sendDueReminders } from "@/lib/notifications";

export const runtime = "nodejs";

function authorized(request) {
    const header = request.headers.get("authorization");
    const bearer = header?.startsWith("Bearer ") ? header.slice(7) : null;
    const provided = bearer || new URL(request.url).searchParams.get("secret");
    return Boolean(provided) && provided === process.env.CRON_SECRET;
}

export async function GET(request) {
    if (!authorized(request)) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    try {
        const admin = await getSupabaseAdminClient();
        const result = await sendDueReminders(admin);
        return NextResponse.json({ ok: true, ...result });
    } catch (err) {
        return NextResponse.json({ error: err.message }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { getAnthropicClient } from "@/lib/anthropic/client";
import Anthropic from "@anthropic-ai/sdk";
import { createClient } from "@/lib/supabase/server";
import { z } from "zod";

const SYSTEM_PROMPT = `You are a botanist specializing in plant identification. You are shown a single photo of a plant and must identify the most likely species.

Return ONLY a JSON object — NO MARKDOWN, NO CODE FENCES, NO PREAMBLE OR EXPLANATION — matching exactly this shape:
{
  "primary": { "common_name": string, "scientific_name": string, "confidence": number, "type": "houseplant" | "succulent" | "cacti" | "flowering" | "tree" | "shrub" | "herb" | "edible" | "fern" | "palm" | "other" },
  "alternatives": [ { "common_name": string, "scientific_name": string, "confidence": number, "type": "houseplant" | "succulent" | "cacti" | "flowering" | "tree" | "shrub" | "herb" | "edible" | "fern" | "palm" | "other" } ],
  "visible_health_issues": [ string ],
  "note": string (optional)
}

Rules:
- "confidence" is a decimal between 0 and 1.
- "primary" is your single best guess. "alternatives" holds up to 2 other plausible species, most likely first.
- "type" is the broadest applicable category from the listed enum. Use "houseplant" for foliage plants typically grown indoors; "succulent" for non-cactus succulents (e.g. Aloe, Jade, Echeveria); "cacti" for cacti; "flowering" when blooms are the main feature; "tree" or "shrub" for woody outdoor specimens; "herb" for culinary/medicinal herbs (basil, mint, lavender); "edible" for fruit/vegetable crops; "fern" for ferns; "palm" for palms; "other" only when none fit.
- "visible_health_issues" lists visible problems (e.g. "yellowing lower leaves", "brown leaf tips", "signs of pests"). Use an empty array if none are visible.
- If the image contains no identifiable plant, set primary.confidence to 0, use primary.common_name "Unknown" with scientific_name "" and type "other", leave alternatives empty, and explain in "note".
- Prefer widely-kept houseplant species.
- Output valid JSON and nothing else.`;

export async function POST(request) {
  const guessSchema = z.object({
    common_name: z.string(),
    scientific_name: z.string(),
    confidence: z.number().min(0).max(1),
    type: z.enum(["houseplant", "succulent", "cacti", "flowering", "tree", "shrub", "herb", "edible", "fern", "palm", "other"]),
  });

  const mainSchema = z.object({
    primary: guessSchema,
    alternatives: z.array(guessSchema).default([]),
    visible_health_issues: z.array(z.string()).default([]),
    note: z.string().optional(),
  })

  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

  const body = await request.json();
  if (!body.img) return NextResponse.json({ error: "Missing image file." }, { status: 400 });

  try {
    const anthropic = getAnthropicClient();
    const response = await anthropic.messages.create({
      model: process.env.ANTHROPIC_AI_MODEL,
      max_tokens: 1024,
      system: [
        {
          type: "text",
          text: SYSTEM_PROMPT,
          cache_control: { type: "ephemeral" },
        }
      ],
      messages: [
        {
          role: "user",
          content: [
            {
              type: "image",
              source: { type: "base64", media_type: "image/jpeg", data: body.img },
            },
            {
              type: "text",
              text: "Identify this plant. Return ONLY the JSON object.",
            },
          ],
        },
      ]
    })

    console.log("Anthropic response:", response);
    
    const raw = response.content.find((part) => part.type === "text")?.text || "";

    const result = mainSchema.safeParse(JSON.parse(raw));

    if (!result.success) return NextResponse.json({ error: "Model returned invalid response.", details: result.error.errors }, { status: 502 });

    return NextResponse.json(result.data);

  } catch (error) {
    if (error instanceof Anthropic.APIError) return NextResponse.json({ error: `Anthropic API error: ${error.message}` }, { status: 502 });
    if (error instanceof Anthropic.RateLimitError) return NextResponse.json({ error: "Anthropic API rate limit exceeded." }, { status: 503 });
    if (error instanceof Anthropic.BadRequestError) return NextResponse.json({ error: `Anthropic API bad request: ${error.message}` }, { status: 400 });
    if (error instanceof Anthropic.InternalServerError) return NextResponse.json({ error: "Anthropic API internal server error." }, { status: 502 });

    return NextResponse.json({ error: "Failed to identify plant." }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const body = await request.json();

    if (!body) return NextResponse.json({ error: "Missing plant info." }, { status: 400 });

    const { plant, healthIssues, care, tasks, file } = body;

    const { data: imgData, error } = await supabase.storage
        .from("plant-photos")
        .upload(`${user.id}/${crypto.randomUUID()}.jpg`, Buffer.from(file, "base64"), { contentType: "image/jpeg", });

    try {
        const { data: plantData, error: plantError } = await supabase
            .from("plants")
            .insert({
                user_id: user.id,

                species_scientific: plant.species_scientific,
                species_common: plant.species_common || null,

                photo_url: imgData?.path || null,

                type: plant.type || "other",

                health_issues: healthIssues || null,

                location: plant.location || null,
                nickname: plant.nickname || null,
                acquired_at: plant.acquiredAt || null,
            })
            .select("id")
            .single();

        if (error || plantError) return NextResponse.json({ error: "Failed to save plant data." }, { status: 500 });

        const { data: taskData, error: taskError } = await supabase
            .from("care_tasks")
            .insert(
                tasks.map((task) => ({
                    task_type: task.task_type,
                    interval_days: task.interval_days,
                    paused: task.paused,
                    next_due_at: new Date(Date.now() + task.interval_days * 24 * 60 * 60 * 1000).toISOString(),
                    plant_id: plantData.id
                }))
            );

        return NextResponse.json({ success: true, plantId: plantData.id });
    } catch (error) {
        console.error("Error during plant saving:", error);
        return NextResponse.json({ error: "An unexpected error occurred." }, { status: 500 });
    }
}

export async function DELETE(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const body = await request.json();

    if (!body) return NextResponse.json({ error: "Missing plant info." }, { status: 400 });

    const { list } = body;

    try {
        const response = await supabase.from("plants").delete().in("id", list);

        return NextResponse.json({ response: response.data });
    } catch (error) {
        console.error("Error during plant deleting:", error);
        return NextResponse.json({ error: "An unexpected error occurred." }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const { taskId } = await request.json();

    if (!taskId) return NextResponse.json({ error: "Missing task id." }, { status: 400 });

    const { data: task, error } = await supabase
        .from("care_tasks")
        .select("id, interval_days")
        .eq("id", taskId)
        .maybeSingle();

    if (!task) return NextResponse.json({ error: "Task not found." }, { status: 404 });

    const next_due_at = new Date(Date.now() + task.interval_days * 24 * 60 * 60 * 1000).toISOString();

    const { error: updateError } = await supabase
        .from("care_tasks")
        .update({ next_due_at })
        .eq("id", taskId);

    if (updateError) return NextResponse.json({ error: "Failed to update task." }, { status: 500 });

    return NextResponse.json({ next_due_at });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const { taskId, interval_days, paused } = await request.json();

    if (!taskId) return NextResponse.json({ error: "Missing task id." }, { status: 400 });

    const { data: task, error } = await supabase
        .from("care_tasks")
        .select("id, interval_days, paused")
        .eq("id", taskId)
        .maybeSingle();

    if (!task) return NextResponse.json({ error: "Task not found." }, { status: 404 });

    const newInterval = interval_days ?? task.interval_days;
    const patch = {};

    if (interval_days !== undefined) patch.interval_days = newInterval;
    if (paused !== undefined) patch.paused = paused;

    if (paused === false && task.paused === true) {
        patch.next_due_at = new Date(Date.now() + newInterval * 24 * 60 * 60 * 1000).toISOString();
    }

    if (Object.keys(patch).length === 0) return NextResponse.json({ error: "Nothing to update." }, { status: 400 });

    const { data: updated, error: updateError } = await supabase
        .from("care_tasks")
        .update(patch)
        .eq("id", taskId)
        .select("id, interval_days, paused, next_due_at")
        .single();

    if (updateError) return NextResponse.json({ error: "Failed to update task." }, { status: 500 });

    return NextResponse.json(updated);
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function GET() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const { data } = await supabase
        .from("profiles")
        .select("timezone, reminder_hour")
        .eq("id", user.id)
        .maybeSingle();

    return NextResponse.json({
        timezone: data?.timezone ?? null,
        reminder_hour: data?.reminder_hour ?? 9,
    });
}

export async function PUT(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const { timezone, reminder_hour } = await request.json();
    const patch = {};

    if (timezone !== undefined) {
        if (typeof timezone !== "string" || timezone.length > 64) {
            return NextResponse.json({ error: "Invalid timezone." }, { status: 400 });
        }
        patch.timezone = timezone;
    }

    if (reminder_hour !== undefined) {
        if (!Number.isInteger(reminder_hour) || reminder_hour < 0 || reminder_hour > 23) {
            return NextResponse.json({ error: "Invalid reminder hour." }, { status: 400 });
        }
        patch.reminder_hour = reminder_hour;
    }

    if (Object.keys(patch).length === 0) {
        return NextResponse.json({ error: "Nothing to update." }, { status: 400 });
    }

    const { error } = await supabase.from("profiles").update(patch).eq("id", user.id);
    if (error) return NextResponse.json({ error: "Failed to save preferences." }, { status: 500 });

    return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const { subscription, timezone } = await request.json();

    if (!subscription?.endpoint) {
        return NextResponse.json({ error: "Invalid subscription." }, { status: 400 });
    }

    const patch = { push_subscription: subscription };
    if (typeof timezone === "string" && timezone.length <= 64) patch.timezone = timezone;

    const { error } = await supabase
        .from("profiles")
        .update(patch)
        .eq("id", user.id);

    if (error) return NextResponse.json({ error: "Failed to save subscription." }, { status: 500 });

    return NextResponse.json({ ok: true });
}

export async function DELETE() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });

    const { error } = await supabase
        .from("profiles")
        .update({ push_subscription: null })
        .eq("id", user.id);

    if (error) return NextResponse.json({ error: "Failed to clear subscription." }, { status: 500 });

    return NextResponse.json({ ok: true });
}

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

export async function GET(request) {
    const { searchParams, origin } = new URL(request.url);
    const code = searchParams.get('code');

    // parameters for email signin callback
    const token_hash = searchParams.get('token_hash');
    const type = searchParams.get('type');

    let next = searchParams.get('next') ?? '/';

    if (!next.startsWith('/')) {
        next = '/'
    }

    const supabase = await createClient();
    let error;
    if (code) {
        ({ error } = await supabase.auth.exchangeCodeForSession(code));
    } else if (token_hash && type) {
        ({ error } = await supabase.auth.verifyOtp({
            token_hash: token_hash,
            type: type,
        }));
    }

    if (!error) {
        const forwardedHost = request.headers.get('x-forwarded-host');
        const isLocalEnv = process.env.NODE_ENV === 'development';

        if (isLocalEnv) {
            return NextResponse.redirect(new URL(next, origin));
        } else if (forwardedHost) {
            return NextResponse.redirect(new URL(next, `https://${forwardedHost}`));
        } else {
            return NextResponse.redirect(new URL(next, origin));
        }
    }

    return NextResponse.redirect(new URL('/auth/auth-code-error', origin));
}

import { Geist, Geist_Mono } from "next/font/google";
import { SerwistProvider } from "@serwist/next/react";
import "./globals.css";

