import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

export default async function Home() {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  redirect(user ? "/plants" : "/signin");
}

import { createClient } from "@/lib/supabase/server";
import { getSupabaseAdminClient } from "@/lib/supabase/admin";
import { redirect } from "next/navigation";
import MainView from "@/components/details/MainView";

export default async function PlantDetail({ params }) {
    const { id } = await params;
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/signin");

    const { data: plant, error } = await supabase
        .from("plants")
        .select("*")
        .eq("id", id)
        .maybeSingle();

    const { data: signed } = await supabase.storage
        .from("plant-photos")
        .createSignedUrl(plant.photo_url, 3600);


    const { data: tasks } = await supabase
        .from("care_tasks")
        .select("*")
        .eq("plant_id", id)
        .order("next_due_at", { ascending: true });

    const admin = await getSupabaseAdminClient();
    const { data: profile } = await admin
        .from("care_profiles")
        .select("profile_json")
        .ilike("species_scientific", plant.species_scientific)
        .maybeSingle();

    return (
        <MainView plant={{ ...plant, photo_url: signed?.signedUrl }} tasks={tasks} careProfile={profile?.profile_json} />
    );
}

import MainView from "@/components/new/MainView";

export default async function New() {
    return <MainView />
}

import { createClient } from "@/lib/supabase/server";
import { redirect } from "next/navigation";
import MainView from "@/components/plants/MainView";

export default async function Plants() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/signin");

    const { data, error } = await supabase.from("plants").select("*");

    const paths = data
        .filter(plant => plant.photo_url)
        .map(plant => plant.photo_url);

    const { data: signed, error: signedError } = await supabase.storage
        .from("plant-photos")
        .createSignedUrls(paths, 3600);

    const plantsWithPhotos = data.map((plant) => {
        const signedUrlObj = signed.find((s) => s.path === plant.photo_url);

        return {
            ...plant,
            photo_url: signedUrlObj ? signedUrlObj.signedUrl : null,
        };
    })

    return <MainView plants={plantsWithPhotos} />
}

import Form from "@/components/signin/Form";

export default function SignIn() {
  return <Form />;
};

import { defaultCache } from "@serwist/next/worker";
import { Serwist, StaleWhileRevalidate, CacheFirst } from "serwist";

const serwist = new Serwist({
    precacheEntries: self.__SW_MANIFEST,
    skipWaiting: true,
    clientsClaim: true,
    navigationPreload: true,
    runtimeCaching: defaultCache
});

serwist.addEventListeners();

self.addEventListener("push", (event) => {
    if (!event.data) return;

    let payload = {};
    try {
        payload = event.data.json();
    } catch {
        payload = { title: "Plant Care", body: event.data.text() };
    }

    const title = payload.title || "Plant Care";
    const options = {
        body: payload.body || "",
        icon: payload.icon || "/icons/image_192x192.png",
        badge: payload.badge || "/icons/image_192x192.png",
        tag: payload.tag || "plant-care-due",
        data: { url: payload.url || "/plants" },
    };

    event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener("notificationclick", (event) => {
    event.notification.close();
    const url = event.notification.data?.url || "/plants";

    event.waitUntil(
        self.clients
            .matchAll({ type: "window", includeUncontrolled: true })
            .then((clients) => {
                for (const client of clients) {
                    if ("focus" in client) {
                        client.navigate(url);
                        return client.focus();
                    }
                }
                return self.clients.openWindow(url);
            }),
    );
});

