                                onChange={(e) => setCustomName(e.target.value)}
                                placeholder="e.g. Prune"
                                className="w-full rounded-xl border border-stone-200 bg-white px-3 py-2.5 text-sm text-stone-900 outline-none focus:border-emerald-400 focus:ring-4 focus:ring-emerald-100"
                            />
                        </label>
                        <div className="w-15">
                            <button
                                type="button"
                                onClick={() => handleCustomTaskAdd()}
                                className="mt-2 flex w-full cursor-pointer items-center justify-center gap-2 rounded-xl bg-emerald-500 px-4 py-3 text-sm font-medium text-white hover:bg-emerald-600"
                            >
                                <PiPlusBold className="h-4 w-4" />
                            </button>
                        </div>
                    </div>
                ) : (
                    <button
                        type="button"
                        onClick={() => setAddingCustomTask(true)}
                        className="flex w-full cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-stone-300 px-4 py-3 text-sm text-stone-600 hover:border-emerald-400 hover:text-emerald-700"
                    >
                        <PiPlusBold className="h-4 w-4" />
                        Add custom task
                    </button>
                )}

            </div>

            {careSettings && (
                <div className="space-y-3">
                    <div>
                        <h2 className="text-base font-semibold text-stone-900">Plant needs</h2>
                        <p className="text-xs text-stone-500">
                            From the AI-generated care profile.
                        </p>
                    </div>

                    <div className="divide-y divide-stone-100 overflow-hidden rounded-xl border border-stone-200">
                        <div className="flex items-start gap-3 bg-white px-4 py-3">
                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-emerald-50">
                                <PiSunFill className="h-5 w-5 text-emerald-500" />
                            </div>
                            <div className="min-w-0 flex-1">
                                <p className="font-medium text-stone-900">Light – {careSettings.light?.level}</p>
                                {careSettings.light?.notes && (
                                    <p className="mt-1 text-xs leading-relaxed text-stone-500">
                                        {careSettings.light.notes}
                                    </p>
                                )}
                            </div>
                        </div>

                        <div className="flex items-start gap-3 bg-white px-4 py-3">
                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-emerald-50">
                                <PiCloudFill className="h-5 w-5 text-emerald-500" />
                            </div>
                            <div className="min-w-0 flex-1">
                                <p className="font-medium text-stone-900">Humidity – {careSettings.humidity?.level}</p>
                                {careSettings.humidity?.notes && (
                                    <p className="mt-1 text-xs leading-relaxed text-stone-500">
                                        {careSettings.humidity.notes}
                                    </p>
                                )}
                            </div>
                        </div>

                        <div className="flex items-start gap-3 bg-white px-4 py-3">
                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-emerald-50">
                                <PiThermometerFill className="h-5 w-5 text-emerald-500" />
                            </div>
                            <div className="min-w-0 flex-1">
                                <p className="font-medium text-stone-900">Temperature {careSettings.temperature_range_c
                                    ? `${careSettings.temperature_range_c[0]}–${careSettings.temperature_range_c[1]} °C`
                                    : "—"}
                                </p>
                                <p className="mt-1 text-xs leading-relaxed text-stone-500">
                                    Comfortable indoor range for this species.
                                </p>
                            </div>
                        </div>

                        <div className="flex items-start gap-3 bg-white px-4 py-3">
                            <div
                                className={
                                    careSettings.toxicity?.pets
                                        ? "flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-amber-50"
                                        : "flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-emerald-50"
                                }
                            >
                                <PiPawPrintFill
                                    className={
                                        careSettings.toxicity?.pets
                                            ? "h-5 w-5 text-amber-500"
                                            : "h-5 w-5 text-emerald-500"
                                    }
                                />
                            </div>
                            <div className="min-w-0 flex-1">
                                <p
                                    className={
                                        careSettings.toxicity?.pets
                                            ? "font-medium text-amber-700"
                                            : "font-medium text-stone-500"
                                    }
                                >
                                    {careSettings.toxicity?.pets ? "Toxic to pets" : "Pet safe"}
                                </p>
                                {careSettings.toxicity?.notes && (
                                    <p className="mt-1 text-xs leading-relaxed text-stone-500">
                                        {careSettings.toxicity.notes}
                                    </p>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <div className="flex items-center justify-between gap-3 pt-2">
                <button
                    type="button"
                    onClick={onBack}
                    className="flex cursor-pointer items-center gap-2 rounded-xl border border-stone-200 bg-white px-4 py-2.5 text-sm font-medium text-stone-700 hover:bg-stone-50"
                >
                    <FaArrowLeft className="h-3.5 w-3.5" />
                    Back
                </button>
                <button
                    type="button"
                    onClick={() => onSave(tasks)}
                    disabled={loading}
                    className="cursor-pointer rounded-xl bg-emerald-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-emerald-600"
                >
                    Save Plant
                </button>
            </div>
        </div>
    );
}

"use client";

import { useRef } from "react";
import Image from "next/image";
import { FaCamera, FaImage, FaXmark } from "react-icons/fa6";
import { PiSparkleFill } from "react-icons/pi";

export default function Identify({ photo, onPhotoChange, onIdentify, loading = false }) {
    const cameraRef = useRef(null);
    const fileRef = useRef(null);

    const handleFile = (e) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const previewUrl = URL.createObjectURL(file);
        onPhotoChange({ file, previewUrl });
        e.target.value = "";
    };

    const clearPhoto = () => {
        if (photo?.previewUrl) URL.revokeObjectURL(photo.previewUrl);
        onPhotoChange(null);
    };

    return (
        <div className="space-y-6 rounded-2xl border border-stone-200 bg-white p-6 shadow-sm">
            <div className="space-y-1 text-center">
                <h1 className="text-2xl font-semibold text-stone-900">
                    Identify your plant
                </h1>
                <p className="text-sm text-stone-600">
                    Snap a photo or pick one from your device. Clear shots of leaves work best.
                </p>
            </div>

            <div className="relative flex aspect-square w-full items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed border-stone-300 bg-stone-50">
                {photo ? (
                    <>
                        <Image
                            src={photo.previewUrl}
                            alt="Selected plant"
                            fill
                            sizes="(max-width: 768px) 100vw, 600px"
                            className="object-cover"
                            unoptimized
                        />
                        {loading && (
                            <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-stone-900/40 backdrop-blur-sm">
                                <span className="h-10 w-10 animate-spin rounded-full border-4 border-white/30 border-t-white" />
                                <p className="text-sm font-medium text-white">
                                    Identifying your plant...
                                </p>
                            </div>
                        )}
                        {!loading && (
                            <button
                                type="button"
                                onClick={clearPhoto}
                                className="absolute right-3 top-3 flex h-9 w-9 cursor-pointer items-center justify-center rounded-full bg-white/90 text-stone-700 shadow hover:bg-white"
                                aria-label="Remove photo"
                            >
                                <FaXmark className="h-4 w-4" />
                            </button>
                        )}
                    </>
                ) : (
                    <div className="flex flex-col items-center gap-2 text-stone-500">
                        <div className="flex h-16 w-16 items-center justify-center rounded-full bg-emerald-50">
                            <FaImage className="h-7 w-7 text-emerald-500" />
                        </div>
                        <p className="text-sm">No photo selected yet</p>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-2 gap-3">
                <button
                    type="button"
                    onClick={() => cameraRef.current?.click()}
                    disabled={loading}
                    className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-stone-200 bg-white px-4 py-3 text-sm font-medium text-stone-800 transition hover:border-emerald-400 hover:text-emerald-700 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-stone-200 disabled:hover:text-stone-800"
                >
                    <FaCamera className="h-4 w-4" />
                    Take Photo
                </button>
                <button
                    type="button"
                    onClick={() => fileRef.current?.click()}
                    disabled={loading}
                    className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-stone-200 bg-white px-4 py-3 text-sm font-medium text-stone-800 transition hover:border-emerald-400 hover:text-emerald-700 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-stone-200 disabled:hover:text-stone-800"
                >
                    <FaImage className="h-4 w-4" />
                    From Device
                </button>
            </div>

            <input
                ref={cameraRef}
                type="file"
                accept="image/*"
                capture="environment"
                hidden
                onChange={handleFile}
            />
            <input
                ref={fileRef}
                type="file"
                accept="image/*"
                hidden
                onChange={handleFile}
            />

            <button
                type="button"
                disabled={!photo || loading}
                onClick={() => onIdentify(photo?.file)}
                className="flex w-full cursor-pointer items-center justify-center gap-2 rounded-xl bg-emerald-500 px-4 py-3 font-semibold text-white transition hover:bg-emerald-600 disabled:cursor-not-allowed disabled:bg-stone-200 disabled:text-stone-400"
            >
                {loading ? (
                    <>
                        <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />
                        Identifying...
                    </>
                ) : (
                    <>
                        <PiSparkleFill className="h-4 w-4" />
                        Identify with AI
                    </>
                )}
            </button>
        </div>
    );
}

"use client";

import { useState } from "react";
import { redirect } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { FaArrowLeft } from "react-icons/fa6";
import Identify from "@/components/new/Identify";
import Result from "@/components/new/Result";
import CareSettings from "@/components/new/CareSettings";
import { compressImage, blobToBase64 } from "@/lib/image";

const steps = [
    { key: "identify", label: "Photo" },
    { key: "result", label: "Identify" },
    { key: "care", label: "Care Settings" },
];

export default function MainView() {
    const [step, setStep] = useState("identify");
    const [photo, setPhoto] = useState(null);
    const [selected, setSelected] = useState(null);
    const [loading, setLoading] = useState(false);
    const [identifyResult, setIdentifyResult] = useState(null);
    const [careSettings, setCareSettings] = useState(null);
    const [base64Photo, setBase64Photo] = useState(null);
    const [nickname, setNickname] = useState("");
    const [location, setLocation] = useState("");
    const [acquiredAt, setAcquiredAt] = useState("");

    const currentIndex = steps.findIndex((s) => s.key === step);

    const handleIdentify = async (file) => {
        setLoading(true);
        try {
            const blob = await compressImage(file);
            const img = await blobToBase64(blob);
            setBase64Photo(img);

            const response = await fetch("/api/identify", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ img }),
            });
            const data = await response.json();

            console.log("Identification result:", data);

            const candidates = [
                {
                    species_scientific: data.primary.scientific_name,
                    species_common: data.primary.common_name,
                    confidence: data.primary.confidence,
                    type: data.primary.type,
                },
                ...(data.alternatives || []).map((a) => ({
                    species_scientific: a.scientific_name,
                    species_common: a.common_name,
                    confidence: a.confidence,
                    type: a.type,
                })),
            ];

            setIdentifyResult({
                candidates,
                healthIssues: data.visible_health_issues || [],
                note: data.note || "",
            });
            setSelected(null);
            setStep("result");
        } catch (error) {
            console.error("Network error during identification:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleCareSettings = async (plantName, species) => {
        setLoading(true);
        try {
            const response = await fetch("/api/care", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ plantName, species }),
            });
            const data = await response.json();
            setCareSettings(data);
            setStep("care");
        } catch (error) {
            console.error("Network error during care settings generation:", error);
        } finally {
            setLoading(false);
        }
    }

    const handleSavePlant = async (tasks) => {
        setLoading(true);
        try {
            const response = await fetch("/api/new", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    plant: { ...selected, nickname, location, acquiredAt },
                    healthIssues: identifyResult?.healthIssues || null,
                    care: careSettings,
                    tasks: tasks,
                    file: base64Photo
                }),
            });
            await response.json();
            redirect("/plants");
        } catch (error) {
            console.error("Network error during plant saving:", error);
        } finally {
            setLoading(false);
        }
    }

    return (
        <div className="min-h-screen bg-stone-50 p-6 text-stone-900">
            <div className="mx-auto max-w-3xl space-y-6">
                <header className="flex items-center justify-between rounded-full bg-white px-6 py-3 shadow-sm">
                    <Link
                        href="/plants"
                        className="flex items-center gap-2 text-sm text-stone-700 hover:text-emerald-700"
                    >
                        <FaArrowLeft className="h-3.5 w-3.5" aria-hidden="true" />
                        <span>Back to collection</span>
                    </Link>
                    <div className="flex items-center gap-2">
                        <Image
                            src="/icons/image_192x192.png"
                            alt="Plant Care Logo"
                            width={32}
                            height={32}
                            className="flex h-8 w-8 items-center justify-center rounded-md bg-emerald-400 text-white font-bold"
                        />
                        <span className="font-bold text-stone-900 uppercase">Plant Care</span>
                    </div>
                </header>

                <div className="flex items-center justify-center gap-2 text-sm">
                    {steps.map(({ key, label }, i) => {
                        const active = i === currentIndex;
                        const done = i < currentIndex;
                        return (
                            <div key={key} className="flex items-center gap-2">
                                <span
                                    className={
                                        active
                                            ? "flex h-7 w-7 items-center justify-center rounded-full bg-emerald-500 text-xs font-semibold text-white"
                                            : done
                                                ? "flex h-7 w-7 items-center justify-center rounded-full bg-emerald-100 text-xs font-semibold text-emerald-700"
                                                : "flex h-7 w-7 items-center justify-center rounded-full bg-stone-200 text-xs font-semibold text-stone-500"
                                    }
                                >
                                    {i + 1}
                                </span>
                                <span
                                    className={
                                        active
                                            ? "font-medium text-stone-900"
                                            : done
                                                ? "text-emerald-700"
                                                : "text-stone-500"
                                    }
                                >
                                    {label}
                                </span>
                                {i < steps.length - 1 && (
                                    <span className="mx-2 h-px w-8 bg-stone-300" />
                                )}
                            </div>
                        );
                    })}
                </div>

                {step === "identify" && (
                    <Identify
                        photo={photo}
                        onPhotoChange={setPhoto}
                        onIdentify={handleIdentify}
                        loading={loading}
                    />
                )}

                {step === "result" && (
                    <Result
                        photo={photo}
                        candidates={identifyResult?.candidates}
                        healthIssues={identifyResult?.healthIssues}
                        note={identifyResult?.note}
                        selected={selected}
                        onSelect={setSelected}
                        onBack={() => setStep("identify")}
                        onContinue={() =>
                            handleCareSettings(
                                selected?.species_common,
                                selected?.species_scientific,
                            )
                        }
                        loading={loading}
                    />
                )}

                {step === "care" && (
                    <CareSettings
                        photo={photo}
                        plant={selected}
                        careSettings={careSettings}
                        onBack={() => setStep("result")}
                        onSave={handleSavePlant}
                        loading={loading}
                        nickname={nickname}
                        onNicknameChange={setNickname}
                        setLocation={setLocation}
                        location={location}
                        acquiredAt={acquiredAt}
                        setAcquiredAt={setAcquiredAt}
                    />
                )}
            </div>
        </div>
    );
}

"use client";

import Image from "next/image";
import { useState } from "react";
import { FaArrowLeft, FaArrowRight, FaCheck } from "react-icons/fa6";
import { PiPottedPlantFill, PiWarningFill, PiInfoFill } from "react-icons/pi";

export default function Result({
    photo,
    candidates = [],
    healthIssues = [],
    note = "",
    selected,
    onSelect,
    onBack,
    onContinue,
    loading = false,
}) {
    const [enterCustomName, setEnterCustomName] = useState(false);
    const [customName, setCustomName] = useState("");

    const handleContinue = () => {
        const scientificName = selected?.species_scientific || customName;
        const commonName = selected?.species_common || "";
        onContinue(scientificName, commonName);
    };

    return (
        <div className="space-y-6 rounded-2xl border border-stone-200 bg-white p-6 shadow-sm">
            <div className="flex items-center gap-4">
                <div className="relative h-20 w-20 shrink-0 overflow-hidden rounded-xl bg-stone-100">
                    {photo?.previewUrl && (
                        <Image
                            src={photo.previewUrl}
                            alt="Submitted plant"
                            fill
                            sizes="80px"
                            className="object-cover"
                            unoptimized
                        />
                    )}
                </div>
                <div>
                    <h1 className="text-xl font-semibold text-stone-900">
                        Possible matches
                    </h1>
                    <p className="text-sm text-stone-600">
                        Pick the one that looks right, then continue.
                    </p>
                </div>
            </div>

            {note && (
                <div className="flex gap-3 items-center rounded-xl bg-emerald-50/60 p-4">
                    <PiInfoFill className="h-5 w-5 shrink-0 text-emerald-600" />
                    <p className="text-sm leading-relaxed text-stone-700">{note}</p>
                </div>
            )}

            <div className="space-y-3">
                {candidates.map((c) => {
                    const isSelected = selected?.species_scientific === c.species_scientific;
                    const pct = Math.round(c.confidence * 100);
                    return (
                        <div key={c.species_scientific}>
                            <button
                                type="button"
                                onClick={() => { onSelect(c) }}
                                className={
                                    isSelected
                                        ? "flex w-full cursor-pointer items-center gap-4 rounded-xl border-2 border-emerald-500 bg-emerald-50/50 p-4 text-left transition"
                                        : "flex w-full cursor-pointer items-center gap-4 rounded-xl border border-stone-200 bg-white p-4 text-left transition hover:border-emerald-300"
                                }
                            >
                                <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-lg bg-emerald-50">
                                    <PiPottedPlantFill className="h-6 w-6 text-emerald-500" />
                                </div>

                                <div className="min-w-0 flex-1">
                                    <p className="truncate font-medium italic text-stone-900">
                                        {c.species_scientific}
                                    </p>
                                    <p className="truncate text-sm text-stone-600">
                                        {c.species_common}
                                    </p>
                                    <div className="mt-2 flex items-center gap-2">
                                        <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-stone-100">
                                            <div
                                                className="h-full rounded-full bg-emerald-400"
                                                style={{ width: `${pct}%` }}
                                            />
                                        </div>
                                        <span className="w-10 text-right text-xs font-medium text-stone-600">
                                            {pct}%
                                        </span>
                                    </div>
                                </div>

                                <div
                                    className={
                                        isSelected
                                            ? "flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500 text-white"
                                            : "h-6 w-6 shrink-0 rounded-full border-2 border-stone-300"
                                    }
                                >
                                    {isSelected && <FaCheck className="h-3 w-3" />}
                                </div>
                            </button>
                        </div>
                    );
                })}
            </div>

            {healthIssues.length > 0 && (
                <div className="flex items-center rounded-xl border border-amber-200 bg-amber-50/60 p-4">
                    <PiWarningFill className="mb-2 h-5 w-5 text-amber-600" />
                    <div className="mb-2 gap-2">
                        <h2 className="ml-7 flex items-center text-sm font-semibold text-amber-900">
                            Visible health issues
                        </h2>
                        <div className="ml-7 list-disc space-y-1 text-sm text-amber-900/80">
                            {healthIssues.map((issue, i) => (
                                <div key={i}>• {issue}</div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {enterCustomName ? (
                <div>
                    <label className="block">
                        <span className="mb-1 block text-sm font-medium text-stone-700">
                            Plant name
                        </span>
                        <input
                            type="text"
                            value={customName}
                            onChange={
                                (e) => setCustomName(e.target.value)
                            }
                            placeholder="e.g. Jade Plant"
                            className="w-full rounded-xl border border-stone-200 bg-white px-3 py-2.5 text-sm text-stone-900 outline-none focus:border-emerald-400 focus:ring-4 focus:ring-emerald-100"
                        />
                    </label>
                </div>
            ) : (
                <button
                    type="button"
                    onClick={() => {
                        setEnterCustomName(true);
                        onSelect(null);
                    }}
                    className="w-full cursor-pointer rounded-xl border border-dashed border-stone-300 px-4 py-3 text-sm text-stone-600 hover:border-stone-400 hover:text-stone-800"
                >
                    None of these match
                </button>
            )}

            <div className="flex items-center justify-between gap-3 pt-2">
                <button
                    type="button"
                    onClick={onBack}
                    disabled={loading}
                    className="flex cursor-pointer items-center gap-2 rounded-xl border border-stone-200 bg-white px-4 py-2.5 text-sm font-medium text-stone-700 hover:bg-stone-50 disabled:cursor-not-allowed disabled:opacity-50"
                >
                    <FaArrowLeft className="h-3.5 w-3.5" />
                    Retake
                </button>
                <button
                    type="button"
                    disabled={(!selected && !customName) || loading}
                    onClick={() => handleContinue()}
                    className="flex cursor-pointer items-center gap-2 rounded-xl bg-emerald-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-emerald-600 disabled:cursor-not-allowed disabled:bg-stone-200 disabled:text-stone-400"
                >
                    {loading ? (
                        <>
                            <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />
                            Generating care...
                        </>
                    ) : (
                        <>
                            Continue
                            <FaArrowRight className="h-3.5 w-3.5" />
                        </>
                    )}
                </button>
            </div>
        </div>
    );
}

